111: }
112: 
113: /** ISO 시각 → "2026. 7. 17 07:12" (초·오전/오후 없이 한 줄). 파싱 실패 시 빈 문자열. */
114: function formatSavedDateTime(iso: string): string {
115:   const t = Date.parse(iso);
116:   if (!Number.isFinite(t)) return "";
117:   const d = new Date(t);
118:   const date = `${d.getFullYear()}. ${d.getMonth() + 1}. ${d.getDate()}`;
119:   const hh = String(d.getHours()).padStart(2, "0");
120:   const mm = String(d.getMinutes()).padStart(2, "0");
121:   return `${date} ${hh}:${mm}`;
122: }
123: 
124: export type SavedRoutesPanelProps = {
125:   routes: SavedRoute[];
126:   /** 이름 검색어 — 입력칸은 모달 제목 줄(`RouteListModalShell`)에 있다 */
127:   queryText: string;
128:   loading: boolean;
129:   /** 게스트(localStorage 만 사용) 안내 표시 여부 */
130:   guestNotice: boolean;
131:   /** 세션이 idle 일 때만 불러오기·삭제 허용 */
132:   sessionIdle: boolean;
133:   /** 공개 등록 심사 중인 savedRouteId (Firestore 신청 기준) */
134:   pendingPublicRouteIds?: ReadonlySet<string>;
135:   /** 이미 퍼블릭 코스로 승인·등록된 원본 savedRouteId (`courses.sourceSavedRouteId`) */
136:   publishedPublicSavedRouteIds?: ReadonlySet<string>;
137:   /** 퍼블릭 게시 코스와 동일한 경로 지문(카탈로그 밖 코스까지 DB 조회) */
138:   publishedPublicRouteFingerprints?: ReadonlySet<string>;
139:   /** 로그인 사용자: 완주 경로 퍼블릭 등록 모달 열기(게스트는 동일 라벨 비활성 버튼만 표시) */
140:   onOpenPublicRequest?: (route: SavedRoute) => void;
141:   onLoadRoute: (route: SavedRoute) => void;
142:   /**
143:    * 미완주 「이어 달리기」 — 슬롯 대상 확보/교체 후 로드.
144:    * 없으면 onLoadRoute 로 폴백(대기·완주 「열기」는 항상 onLoadRoute).
145:    */
146:   onResumeRoute?: (route: SavedRoute) => void;
147:   /** 현재 이어달리기 슬롯 활성 경로 — 「이어달리기 중」 배지 */
148:   activeResumeRouteId?: string | null;
149:   onRenameRoute: (route: SavedRoute, newName: string) => Promise<void> | void;
150:   onDeleteRoute: (route: SavedRoute) => Promise<void> | void;
151:   /** 미완료 쿼터 초과로 유도됐을 때 상단에 표시할 안내(없으면 미표시) */
152:   quotaNotice?: string | null;
153:   onDismissQuotaNotice?: () => void;
154:   /** 값이 바뀔 때마다 완주 필터를 「대기」로 전환(미완료 초과 유도용). 0=무동작 */
155:   focusPendingSignal?: number;
156: };
157: 
158: /** 선택된 경로에 대해 「공개」 툴바 버튼의 활성 여부·안내를 판정. */
159: type PublicActionState =
160:   | { kind: "unavailable"; title: string } // 게스트·핸들러 없음: 비활성
161:   | { kind: "in-review"; title: string } // 심사 중: 비활성
162:   | { kind: "already-public"; title: string } // 이미 퍼블릭: 비활성
163:   | { kind: "ready"; title: string }; // 신청 가능: 활성
164: 
165: export function SavedRoutesPanel(props: SavedRoutesPanelProps) {
166:   const [renamingId, setRenamingId] = useState<string | null>(null);
167:   const [renameDraft, setRenameDraft] = useState("");
168:   const [busyId, setBusyId] = useState<string | null>(null);
169:   const [error, setError] = useState<string | null>(null);
170:   const [filter, setFilter] = useState<CompletionFilter>("all");
171:   const [selectedId, setSelectedId] = useState<string | null>(null);
172:   const queryText = props.queryText;
173:   const [sortKey, setSortKey] = useState<RouteSortKey>("recent");
174: 
175:   // 미완료 쿼터 초과 유도 시 「대기」 필터로 전환해 정리 대상 경로만 보여준다.
176:   // effect 대신 이전 신호값과 비교(React 권장) — cascading render·set-state-in-effect 회피.
177:   const focusPendingSignal = props.focusPendingSignal ?? 0;
178:   const [prevFocusPendingSignal, setPrevFocusPendingSignal] = useState(focusPendingSignal);
179:   if (focusPendingSignal !== prevFocusPendingSignal) {
180:     setPrevFocusPendingSignal(focusPendingSignal);
181:     if (focusPendingSignal > 0) setFilter("pending");
182:   }
183: 
184:   const filtered = useMemo(() => {
185:     const q = normalizeForSearch(queryText);
186:     const base = props.routes.filter((r) => {
187:       if (filter !== "all" && completionState(r) !== filter) return false;
188:       if (q && !normalizeForSearch(r.name).includes(q)) return false;
189:       return true;
190:     });
191:     // 비교 규칙은 `lib/route/routeListSort` 단일 진실 — 공식 코스 목록과 같은 것을 쓴다
192:     return sortRouteList(base, sortKey, (r) => ({
193:       name: r.name,
194:       distanceMeters: r.distanceMeters,
195:       updatedAtMs: Date.parse(r.updatedAtIso),
196:     }));
197:   }, [props.routes, filter, queryText, sortKey]);
198: 
199:   const stateCounts = useMemo(() => {
200:     const counts: Record<CompletionState, number> = { completed: 0, incomplete: 0, pending: 0 };
201:     for (const r of props.routes) counts[completionState(r)] += 1;
202:     return counts;
203:   }, [props.routes]);
204: 
205:   // 선택된 경로 — 목록에서 사라졌으면(필터·검색·삭제) 선택 없음으로 취급.
206:   const selectedRoute = useMemo(
207:     () => (selectedId ? (filtered.find((r) => r.id === selectedId) ?? null) : null),
208:     [filtered, selectedId],
209:   );
210: 
211:   // 선택 경로에 대한 「공개」 툴바 버튼 판정(기존 카드별 분기 로직을 선택 기반으로 이관).
212:   const publicActionState: PublicActionState = useMemo(() => {
213:     if (!selectedRoute) return { kind: "unavailable", title: "경로를 선택하세요" };
214:     if (props.guestNotice || !props.onOpenPublicRequest)
215:       return { kind: "unavailable", title: "로그인을 하면 공개 신청 기능을 쓸 수 있습니다." };
216:     if (props.pendingPublicRouteIds?.has(selectedRoute.id))
217:       return { kind: "in-review", title: "관리자 심사 대기 중" };
218:     const routeFp = fingerprintFromCanonicalSync(
219:       encodeCanonicalRouteGeometryProfile(selectedRoute.geometry, selectedRoute.profile),
220:     );
221:     const alreadyPublishedPublic =
222:       (props.publishedPublicSavedRouteIds?.has(selectedRoute.id) ?? false) ||
223:       (props.publishedPublicRouteFingerprints?.has(routeFp) ?? false);
224:     if (alreadyPublishedPublic)
225:       return { kind: "already-public", title: "이미 퍼블릭 경로입니다" };
226:     if (!props.sessionIdle)
227:       return { kind: "ready", title: "주행 종료 후 사용 가능" };
228:     return { kind: "ready", title: "공개 등록 신청" };
229:   }, [
230:     selectedRoute,
231:     props.guestNotice,
232:     props.onOpenPublicRequest,
233:     props.pendingPublicRouteIds,
234:     props.publishedPublicSavedRouteIds,
235:     props.publishedPublicRouteFingerprints,
236:     props.sessionIdle,
237:   ]);
238: 
239:   // 툴바 버튼 활성 조건 — 선택 있음 + (해당 액션은 idle 필요).
240:   const hasSelection = selectedRoute !== null;
241:   const actionsEnabled = hasSelection && props.sessionIdle && busyId === null;
242:   const publicEnabled = actionsEnabled && publicActionState.kind === "ready";
243: 
244:   function toggleSelect(route: SavedRoute) {
245:     // 다른 카드를 rename 중이었다면 접는다.
246:     if (renamingId && renamingId !== route.id) cancelRename();
247:     setError(null);
248:     setSelectedId((prev) => (prev === route.id ? null : route.id));
249:   }
250: 
251:   function startRename(route: SavedRoute) {
252:     setError(null);
253:     setSelectedId(route.id);
254:     setRenamingId(route.id);
255:     setRenameDraft(route.name);
256:   }
257:   function cancelRename() {
258:     setRenamingId(null);
259:     setRenameDraft("");
260:   }
261:   async function commitRename(route: SavedRoute) {
262:     if (busyId) return;
263:     setBusyId(route.id);
264:     setError(null);
265:     try {
266:       await props.onRenameRoute(route, renameDraft);
267:       setRenamingId(null);
268:       setRenameDraft("");
269:     } catch (e) {
270:       setError(e instanceof Error ? e.message : String(e));
271:     } finally {
272:       setBusyId(null);
273:     }
274:   }
275:   async function commitDelete(route: SavedRoute) {
276:     if (busyId) return;
277:     if (!confirm(`「${route.name}」 경로를 삭제할까요?`)) return;
278:     setBusyId(route.id);
279:     setError(null);
280:     try {
281:       await props.onDeleteRoute(route);
282:       setSelectedId(null);
283:       if (renamingId === route.id) cancelRename();
284:     } catch (e) {
285:       setError(e instanceof Error ? e.message : String(e));
286:     } finally {
287:       setBusyId(null);
288:     }
289:   }
290: 
291:   function onToolbarPublic() {
292:     if (!selectedRoute || !publicEnabled) return;
293:     props.onOpenPublicRequest?.(selectedRoute);
294:   }
295:   function onToolbarOpen() {
296:     if (!selectedRoute || !actionsEnabled) return;
297:     if (isResumeToolbarTarget(selectedRoute) && props.onResumeRoute) {
298:       props.onResumeRoute(selectedRoute);
299:       return;
300:     }
301:     props.onLoadRoute(selectedRoute);
302:   }
303:   function onToolbarRename() {
304:     if (!selectedRoute || !actionsEnabled) return;
305:     startRename(selectedRoute);
306:   }
307:   function onToolbarDelete() {
308:     if (!selectedRoute || !actionsEnabled) return;
309:     void commitDelete(selectedRoute);
310:   }
311: 
312:   const hasRoutes = props.routes.length > 0;
313: 
314:   return (
315:     <section className="saved-routes" aria-label="사용자 경로">
316:       {props.quotaNotice ? (
317:         <div className="saved-routes__quota-notice" role="alert">
318:           <p className="saved-routes__quota-notice-msg">{props.quotaNotice}</p>
319:           <p className="saved-routes__quota-notice-hint">
320:             미완주·대기 경로 중 하나를 완주하거나 삭제하면 새 경로를 저장할 수 있어요.
321:           </p>
322:           {props.onDismissQuotaNotice ? (
323:             <button
324:               type="button"
325:               className="saved-routes__quota-notice-close"
326:               aria-label="안내 닫기"
327:               title="Dismiss"
328:               onClick={props.onDismissQuotaNotice}
329:             >
330:               확인
331:             </button>
332:           ) : null}
333:         </div>
334:       ) : null}
335: 
336:       {props.guestNotice ? (
337:         <p className="saved-routes__notice">
338:           Google 로그인 시 다른 기기에서도 사용할 수 있습니다
339:         </p>
340:       ) : null}
341: 
342:       {hasRoutes ? (
343:         <div className="saved-routes__controls">
344:           <div className="saved-routes__control-row">
345:             <div
346:               className="saved-routes__filter"
347:               role="tablist"
348:               aria-label="사용자 경로 완주 여부 필터"
349:             >
350:               <button
351:                 type="button"
352:                 role="tab"
353:                 aria-selected={filter === "all"}
354:                 className={`saved-routes__filter-btn ${filter === "all" ? "is-active" : ""}`}
355:                 title="Show all"
356:                 onClick={() => setFilter("all")}
357:               >
358:                 전체 ({props.routes.length})
359:               </button>
360:               <button
361:                 type="button"
362:                 role="tab"
363:                 aria-selected={filter === "completed"}
364:                 className={`saved-routes__filter-btn ${filter === "completed" ? "is-active" : ""}`}
365:                 title="Completed only"
366:                 onClick={() => setFilter("completed")}
367:               >
368:                 완주 ({stateCounts.completed})
369:               </button>
370:               <button
371:                 type="button"
372:                 role="tab"
373:                 aria-selected={filter === "incomplete"}
374:                 className={`saved-routes__filter-btn ${filter === "incomplete" ? "is-active" : ""}`}
375:                 title="Ridden but not completed"
376:                 onClick={() => setFilter("incomplete")}
377:               >
378:                 미완주 ({stateCounts.incomplete})
379:               </button>
380:               <button
381:                 type="button"
382:                 role="tab"
383:                 aria-selected={filter === "pending"}
384:                 className={`saved-routes__filter-btn ${filter === "pending" ? "is-active" : ""}`}
385:                 title="Pending only"
386:                 onClick={() => setFilter("pending")}
387:               >
388:                 대기 ({stateCounts.pending})
389:               </button>
390:             </div>
391: 
392:             <RouteSortSelect
393:               value={sortKey}
394:               onChange={setSortKey}
395:               keys={["recent", "distance", "name"]}
396:             />
397:           </div>
398: 
399:           <div className="saved-routes__toolbar" role="toolbar" aria-label="선택한 경로 작업">
400:             <button
401:               type="button"
402:               className="saved-routes__tool saved-routes__tool--accent"
403:               disabled={!publicEnabled}
404:               title={publicActionState.title}
405:               onClick={onToolbarPublic}
406:             >
407:               공개
408:             </button>
409:             <button
410:               type="button"
411:               className="saved-routes__tool saved-routes__tool--primary"
412:               disabled={!actionsEnabled}
413:               title={
414:                 !hasSelection
415:                   ? "경로를 선택하세요"
416:                   : !props.sessionIdle
417:                     ? "주행 종료 후 사용 가능"
418:                     : selectedRoute && isResumeToolbarTarget(selectedRoute)
419:                       ? "이어 달리기"
420:                       : "지도에 경로 불러오기"
421:               }
422:               onClick={onToolbarOpen}
423:             >
424:               {selectedRoute && isResumeToolbarTarget(selectedRoute)
425:                 ? "이어 달리기"
426:                 : "열기"}
427:             </button>
428:             <button
429:               type="button"
430:               className="saved-routes__tool"
431:               disabled={!actionsEnabled}
432:               title={!hasSelection ? "경로를 선택하세요" : "이름 변경"}
433:               onClick={onToolbarRename}
434:             >
435:               이름
436:             </button>
437:             <button
438:               type="button"
439:               className="saved-routes__tool saved-routes__tool--danger"
440:               disabled={!actionsEnabled}
441:               title={!hasSelection ? "경로를 선택하세요" : "경로 삭제"}
442:               onClick={onToolbarDelete}
443:             >
444:               삭제
445:             </button>
446:           </div>
447:         </div>
448:       ) : null}
449: 
450:       {error ? (
451:         <p className="saved-routes__error" role="alert">
452:           {error}
453:         </p>
454:       ) : null}
455: 
456:       {props.loading ? (
457:         <p className="saved-routes__empty">불러오는 중…</p>
458:       ) : props.routes.length === 0 ? (
459:         <p className="saved-routes__empty">
460:           사용자 경로가 없습니다. 「경로」 탭에서 경로를 만든 뒤 「내 경로로 저장」으로 목록에 올려 보세요.
461:           미완료 경로는 90일 후 자동 삭제 · 완주 시 영구 보존
462:         </p>
463:       ) : filtered.length === 0 ? (
464:         <p className="saved-routes__empty">
465:           {normalizeForSearch(queryText)
466:             ? "검색 결과가 없습니다."
467:             : filter === "completed"
468:               ? "아직 완주한 사용자 경로가 없습니다."
469:               : filter === "incomplete"
470:                 ? "미완주 사용자 경로가 없습니다."
471:                 : "대기 중인 사용자 경로가 없습니다."}
472:         </p>
473:       ) : (
474:         <ul className="saved-routes__list" role="listbox" aria-label="사용자 경로 목록">
475:           {filtered.map((route) => {
476:             const isRenaming = renamingId === route.id;
477:             const isBusy = busyId === route.id;
478:             const isSelected = selectedId === route.id;
479:             return (
480:               <li
481:                 key={route.id}
482:                 className={`saved-routes__item ${isSelected ? "is-selected" : ""}`}
483:               >
484:                 {isRenaming ? (
485:                   <div className="saved-routes__rename">
486:                     <input
487:                       className="saved-routes__rename-input"
488:                       type="text"
489:                       maxLength={40}
490:                       value={renameDraft}
491:                       onChange={(e) => setRenameDraft(e.target.value)}
492:                       autoFocus
493:                     />
494:                     <div className="saved-routes__row-actions">
495:                       <button
496:                         type="button"
497:                         className="saved-routes__btn saved-routes__btn--primary"
498:                         disabled={isBusy}
499:                         title="Save name"
500:                         onClick={() => void commitRename(route)}
501:                       >
502:                         저장
503:                       </button>
504:                       <button
505:                         type="button"
506:                         className="saved-routes__btn"
507:                         disabled={isBusy}
508:                         title="Cancel"
509:                         onClick={cancelRename}
510:                       >
511:                         취소
512:                       </button>
513:                     </div>
514:                   </div>
515:                 ) : (
516:                   // 버튼 대신 div: 행 내부에 블록 요소(head/meta/progress)를 담기 때문.
517:                   // <button> 안에 블록 콘텐츠를 넣으면 브라우저가 DOM 을 재구성해 레이아웃이 깨진다.
518:                   <div
519:                     className="saved-routes__row"
520:                     role="option"
521:                     tabIndex={0}
522:                     aria-selected={isSelected}
523:                     onClick={() => toggleSelect(route)}
524:                     onKeyDown={(e) => {
525:                       if (e.key === "Enter" || e.key === " ") {
526:                         e.preventDefault();
527:                         toggleSelect(route);
528:                       }
529:                     }}
530:                   >
531:                     <div className="saved-routes__head">
532:                       <strong className="saved-routes__name" title={route.name}>
533:                         {route.name}
534:                       </strong>
535:                       <div className="saved-routes__head-tags">
536:                         {/* 경로 종류 아이콘이 앞, 완주·대기 배지가 맨 오른쪽(2026-10-06 Chief) */}
537:                         <span
538:                           className="saved-routes__profile"
539:                           title={PROFILE_LABEL[route.profile]}
540:                         >
541:                           <RouteProfileIcon profile={route.profile} />
542:                         </span>
543:                         {(() => {
544:                           if (route.completed === 1) {
545:                             return (
546:                               <span
547:                                 className="saved-routes__badge saved-routes__badge--ok"
548:                                 title={
549:                                   route.completedAtIso
550:                                     ? `Completed: ${new Date(route.completedAtIso).toLocaleString()}`
551:                                     : "Completed · kept permanently"
552:                                 }
553:                               >
554:                                 완주
555:                               </span>
556:                             );
557:                           }
558:                           // 필터와 같은 말을 쓴다 — 달렸으면 미완주, 아니면 대기
559:                           const waitLabel =
560:                             completionState(route) === "incomplete" ? "미완주" : "대기";
561:                           const d = daysUntilExpiry(route.expiresAtIso);
562:                           if (d === null) {
563:                             return (
564:                               <span
565:                                 className="saved-routes__badge saved-routes__badge--pending"
566:                                 title="Pending completion"
567:                               >
568:                                 {waitLabel}
569:                               </span>
570:                             );
571:                           }
572:                           if (d <= 0) {
573:                             return (
574:                               <span
575:                                 className="saved-routes__badge saved-routes__badge--soon"
576:                                 title="Expires soon if not ridden"
577:                               >
578:                                 만료 임박
579:                               </span>
580:                             );
581:                           }
582:                           return (
583:                             <span
584:                               className={`saved-routes__badge ${
585:                                 d <= 2
586:                                   ? "saved-routes__badge--soon"
587:                                   : "saved-routes__badge--pending"
588:                               }`}
589:                               title={`Auto-delete in ${d} day(s) if not ridden`}
590:                             >
591:                               {`${waitLabel} · D-${d}`}
592:                             </span>
593:                           );
594:                         })()}
595:                       </div>
596:                     </div>
597:                     <p className="saved-routes__meta">
