input.newString:
.saved-routes__badge--soon {
  color: #B45309;
  background: rgba(251, 191, 36, 0.14);
  border: 1px solid rgba(180, 83, 9, 0.45);
}

/* ── 지시21: 내 경로 목록 밀도·비교 공간 (아래 전부 내 경로 한정, 입문/퍼블릭·모달 기본 불변) ── */

/* 1. 내 경로가 든 창만 넓게·높게. 높이는 내용 높이(auto)가 원칙이라 0/1/2개는
 * 내용에서 끝나고, 개수가 불어나면 아래 상한까지 자라 목록이 스크롤된다.
 * 로딩·오류·키보드 등 모든 상태에서 상한은 항상 유지된다. */
.oc-modal-overlay:has(.saved-routes) {
  padding: 8px;
}

.oc-modal:has(.saved-routes) {
  width: min(560px, calc(100vw - 16px));
  max-height: calc(100vh - 16px);
  max-height: calc(100dvh - 16px);
}

/* 3. 상단 반복 여백 절제 — 껍데기 패딩도 내 경로가 든 창에만.
 * 폰트·기존 버튼 높이/패딩은 손대지 않음. Guest 안내·필터4·정렬·검색 전부 표시 유지. */
.oc-modal:has(.saved-routes) .oc-modal__head {
  padding: 0.5rem 2.4rem 0.5rem 0.65rem;
}

.oc-modal:has(.saved-routes) .oc-modal__body {
  padding: 0.5rem 0.6rem 0.6rem;
}

/* 2. 선택 없으면 툴바만 접어 목록에 내어준다. 항목을 선택하면 기존 툴바 그대로 표시.
 * disabled·문구·동작은 TSX 그대로, 자리만 조건부. flex 흐름 안이라
 * 목록 스크롤 영역에 자동 반영된다. */
.saved-routes:not(:has(.saved-routes__item.is-selected)) .saved-routes__toolbar {
  display: none;
}

/* 5. 긴 오류·쿼터 안내 overflow 예외 — 평소엔 목록만 스크롤하고, 이 둘이 길어지면
 * 스스로 줄어들어(내부 스크롤, 확인 버튼 포함) 접근 가능. 부모가 잘라 숨기지 않는다. */
.saved-routes > .saved-routes__error,
.saved-routes > .saved-routes__quota-notice {
  flex-shrink: 1;
  min-height: 0;
  overflow-y: auto;
  max-height: 9rem;
  max-height: 30vh;
  max-height: 30dvh;
}

